function [spdout,optim]=SPDoptimizer2(optim)
%optimizes a cluster individual sources for optim.fcns at optim.cct0
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%Required input:
% optim.type_ = 'none'; %'none': fluxes must be supplied!, 'mixer': fluxes are found using colormixer, 'search': fluxes are found using fminsearch
% optim.obs: CIE observer
% target chromaticity:
%   optim.uvYm: cie u'v' chromaticity
%   optim.cct0: CCT(K) (0: choose random CCT and add some random noise to chromaticity
% optim.usesourceorder: 1: include source order in optimization
% optim.routine = 'NSGA-II'; %'none' or 'fminsearch' (not implemented yet(5/09/2014))
% optim.fcns=[]; %handles to individual objective fcn
% %      Example:
%           optim.fcns{1} = @(x) -CIECRI(x);
%           optim.fcns{2} = @(x) -LER_(x);
% optim.fcn_weigths = ones(1,numel(optim.fcns));%weigths for the different fcns
% optim.numberofobjectives = numel(optim.fcns); %number of objectives
% optim.InitChromosome = []; %source parameters (peak wavelength + fwhm + rbas or fluxes (depending on choice of SPDbuildertype
% optim.duvyn = 0; %1: restrict chromaticity to solutions close to blackbody locus (can only be active when mixer is not used)
% optim.lambdas = (360:1:830)'; %wavelength range of SPD
% optim.verbosity=1; %level of output (0: off, >0: on)


if ~isfield(optim,'lambdas');optim.lambdas = (360:1:830)';end
optim.dl = abs(optim.lambdas(1)-optim.lambdas(2));

