]';
cmf10=cmf10(1:dl:end,:);
% if optim.lambdas(1,1)==380;cmf10=cmf10(20/dl+1:end-50/dl,:);end
% if optim.lambdas(1,1)==400& optim.lambdas(end,1)==700;cmf10=cmf10(40/dl+1:end-130/dl,:);end
% if optim.lambdas(1,1)==400& optim.lambdas(end,1)==830;cmf10=cmf10(40/dl+1:end-0/dl,:);end
if optim.obs==2;cmf=cmf2;k=683;else cmf=cmf10;k=683.6;end
cmf=cmf(abs(optim.lambdas(1,1)-cmf(1,1))/dl+1:end-abs(optim.lambdas(end,1)-cmf(end,1))/dl,:);
optim.cmf=cmf;
optim.k=k;

%setup/calculate target chromaticity
if ~isempty(optim.cct0);
    if optim.cct0(1)==0
        %choose random CCT;
        optim.cct0=round(5000+(rand(1)-0.5).*3000);
        optim.addnoise2xyYm=1;
    else % use given
        optim.addnoise2xyYm=0;
    end
    spdBB=blackbodySPD(optim.cct0,optim.lambdas(1),optim.lambdas(end),dl);
    xyzm=100.* [sum(cmf(:,2).*spdBB(:,2)),sum(cmf(:,3).*spdBB(:,2)),sum(cmf(:,4).*spdBB(:,2))]./sum(cmf(:,3).*spdBB(:,2));
    optim.xyYm=xyz2xyY(xyzm);
    optim.uvYm=xyz2uvY(xyY2xyz(optim.xyYm));
    if optim.addnoise2xyYm==1
        optim.uvYm(1:2)=optim.uvYm(1:2)+2.*(rand(1,2)-0.5).*0.005;%add noise in u'v' diagram
        optim.xyYm(1:2)=uv2xy(optim.uvYm(1:2));
        
    end
    
else
    if ~isempty(optim.uvYm);
        optim.xyYm=xyz2xyY(uvY2xyz(optim.uvYm));
        %[optim.cct0,optim.duv0]=CCTa(uvY2xyz(optim.uvYm),optim.obs);
    else
        error('Supply target chromaticity: either using p.cct0 or using p.uvYm');
    end
end

%set min and max fwhm and lambda!
if ~isfield(optim,'minwidth');optim.minwidth=[];end
if ~isfield(optim,'maxwidth');optim.maxwidth=[];end
if ~isfield(optim,'minlambda');optim.minlambda=[];end
if ~isfield(optim,'maxlambda');optim.maxlambda=[];end
if isempty(optim.minwidth);optim.minwidth=0;end
if isempty(optim.maxwidth);optim.maxwidth=100;end
if isempty(optim.maxlambda);optim.maxlambda=optim.lambdas(end);end
if isempty(optim.minlambda);optim.minlambda=optim.lambdas(1);end
optim.Nspds=1;%only one spd is created at a time

%start optimization
clear global best fcn_data
global generalcounter totalcount best fcn_data
switch optim.routine
    %----------------------------------------------------------------------
    case 'none'%don't optimize just build spd with parameters in InitChromosome at cct0 
        if ~isempty(optim.InitChromosome);
            optim.type_='none';
            sp.peakw=optim.InitChromosome(1:optim.nsources);
            sp.fwhm=optim.InitChromosome(optim.nsources+(1:optim.nsources));
            sp.fluxes=optim.InitChromosome(2.*optim.nsources+(1:optim.nsources));
            optim.sp=sp;
            [optim.spdout]=SPDbuilder2(optim,sp);%InitChromosome should dcontain sourcepars for SPDbuilder
        else
            error('No source parameters supplied in InitChromosome!')
        end

    %----------------------------------------------------------------------
    case 'NSGA-II' %start NSGA-II optimization
        clear global chromosome
        global chromosome

        %chromosome=optim.chromosome;
        if ~isfield(optim,'pop');
            optim.pop=[];
        end
        if ~isfield(optim,'gen');
            optim.gen=[];
        end
        if isempty(optim.pop)
            optim.pop=50;
        end
        if isempty(optim.gen)
            optim.gen=5;
        end
        
        %initialize other varariables and parameters
        ndc=0.5;%for screenpareto, allowed distance from blackbody curve
        generalcounter=0;

        %[optim.x,optim.x0,optim.LB,optim.UB]=setupX0_LB_UB(optim.SPDbuildertype,optim.sources,optim.nsources,optim.minlambda,optim.maxlambda,optim.minwidth,optim.maxwidth);%setup starting value x0 and lower and upper bounds, LB & UB
        [optim.x,optim.x0,optim.LB,optim.UB]=setupX0_LB_UB(optim);%setup starting value x0 and lower and upper bounds, LB & UB

        optim.numberofvariables=length(optim.x0);
                
        if ~isfield(optim,'numberofobjectives');
            optim.numberofobjectives=numel(optim.fcns);
        end 
        
        if optim.duvyn==1 & strcmp(optim.type_,'none');
            optim.numberofobjectives=optim.numberofobjectives+1;%1;% min duv is also an objective!!
        end

        %find starting chromosome
        totalcount=optim.pop*optim.gen;
% %         if optim.duvyn==1 & isempty(optim.InitChromosome)
% %             if round(optim.gen/10)>=5;
% %                 ngen=round(optim.gen/10);
% %             else
% %                 ngen=optim.gen;
% %             end
% %             totalcount=totalcount+ngen*optim.pop;
% %             optim.opts=struct('pop',optim.pop,'gen',ngen,'screenpareto',0,'InitChromosome',0);
% %             optim.chromosome=nsga_IIDuv(@(x) FitnessFcn(x,optim),[optim.numberofvariables,optim.numberofobjectives],optim.LB,optim.UB,optim.opts);
% %         end
        if ~isempty(optim.InitChromosome);optim.chromosome=optim.InitChromosome;end
% %         if optim.duvyn==1;
% %                 screenpareto=[3,0,ndc*5.4e-3];
% %                 optim.opts=struct('pop',size(optim.chromosome,1),'gen',optim.gen,'screenpareto',screenpareto,'InitChromosome',optim.chromosome);
% %         else
% %                 screenpareto=0;
% %                 optim.opts=struct('pop',optim.pop,'gen',optim.gen,'screenpareto',screenpareto,'InitChromosome',0);
% %         end
        screenpareto=0;
        optim.opts=struct('pop',optim.pop,'gen',optim.gen,'screenpareto',screenpareto,'InitChromosome',0);
        optim.chromosome=nsga_IIDuv(@(x) FitnessFcn(x,optim),[optim.numberofvariables,optim.numberofobjectives],optim.LB,optim.UB,optim.opts);

 
  
        %calculate optimized spectrum from chromosome
        optim.spdout=[];
        for i=1:size(optim.chromosome,1)
                if optim.verbosity>0
                    disp(sprintf('Calculating spd #%1.0f from chromosome',i));
                end
                x=optim.chromosome(i,1:optim.numberofvariables);
                x=x(1:optim.numberofvariables);

                if isempty(optim.sp.sources)
                    sp.peakw=x(1:optim.nsources);
