%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function [F,spd]=FitnessFcn(x,optim,vars)
global generalcounter totalcount best fcn_data;
generalcounter=generalcounter+1;

%remove additions (values of objectives) made by NSGA-II, because
%SPDbuilder uses size(sourcepars,2) to determine number of sources!!!
x=x(1:optim.numberofvariables);

if isempty(optim.sp.sources)
    sp.peakw=x(1:optim.nsources);
    sp.fwhm=x(optim.nsources+(1:optim.nsources));
    switch optim.type_
        case 'mixer'
            sp.rbas=x(2.*optim.nsources+(1:optim.nsources-3));
            sp.fluxes=nan(1,optim.nsources);
        case 'none'
            sp.fluxes=x(2.*optim.nsources+(1:optim.nsources));
            sp.rbas=nan(1,optim.nsources-3);
        case 'search'
            sp.rbas=nan(1,optim.nsources-3);
            sp.fluxes=nan(1,optim.nsources);
    end
    if optim.usesourceorder==1;
        sp.sourceorder=floor(x(optim.numberofvariables-optim.nsources+1:optim.numberofvariables));
    else
        sp.sourceorder=(1:optim.nsources);
    end
else
    
end

[spd,p,sp]=SPDbuilder2(optim,sp);

%calculate chromaticity & CCT
    %create xyz
  
     xyzwt=100.*[sum(spd(:,2).*optim.cmf(:,2)),sum(spd(:,2).*optim.cmf(:,3)),sum(spd(:,2).*optim.cmf(:,4))]./sum(spd(:,2).*optim.cmf(:,3));%test white
        
    %convert to u'v'
    uvYwt=xyz2uvY(xyzwt);
    
    %calc CCT/duv
    [CCT,Duv]=CCTa(xyzwt,optim.obs);
    
    %calculate duv with target
    uvYm=optim.uvYm;
    duv=sqrt((uvYwt(1)-uvYm(1))^2+(uvYwt(2)-uvYm(2))^2);

%calculate function values of individual objective functions
F=[];
fcn_string=[];
for i=1:numel(optim.fcns)   
    if ~isnan(sum(spd(:,2)))
       [fcn_fv]=optim.fcns{i}(spd);
        F=[F,fcn_fv.*optim.fcn_weigths(i)];
    else
        fcn_fv=nan;
        F=[F,fcn_fv.*optim.fcn_weigths(i)];
    end
    if optim.verbosity==1;
       fcn_string=[fcn_string,sprintf('fcn#%1.0f: %1.3f, ',i,fcn_fv)];
   end
end

F(isnan(abs(F)))=10^3;
F(isinf(abs(F)))=10^3;

%optimize for chromaticity here
if optim.duvyn==1 & strcmp(optim.type_,'none');
    %F=[sign(F).*abs(F)./max(abs(F))]+(duv.*100);
    F=[F,(duv.*1)];
end

F(isnan(abs(F)))=10^3;
F(isinf(abs(F)))=10^3;




switch optim.routine
   case 'NSGA-II'
       %do nothin
   case 'fminsearch'
       %sum F
       F=sum(F(:));
end

if optim.verbosity==1;
    drawnow_01=0;
    F_str_=sprintf('%1.0f/%1.0f: CCT = %1.0f, Duv = %1.5f | DEuv = %1.4f | F = %1.4f | %s | ',generalcounter, totalcount, CCT, Duv, duv, sum(F), fcn_string);
    disp(F_str_)
    if generalcounter==1;best.F=F;best.spd=spd;best.F_str_=F_str_;best.fcn_data=fcn_data;end
    if F<=best.F;best.F=F;best.spd=spd;best.F_str_=F_str_;best.sp=sp;best.fcn_data=fcn_data;drawnow_01=1;end
    figure(111);
    if ~isempty(best.fcn_data);
        subplot(1,3,1);plot_2(spd,'b');title(F_str_)
        subplot(1,3,2);plot_2(best.spd,'b');title(best.F_str_)
        subplot(1,3,3);plot_2(best.fcn_data{1}.xyY1,'go');hold off;
    else
        subplot(1,2,1);plot_2(spd,'b');title(F_str_)
        subplot(1,2,2);plot_2(best.spd,'b');title(best.F_str_)
    end
    if drawnow_01==1;drawnow;drawnow_01=0;end
end

end




%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%NSGA_II genetic algorithm adapted%%%%%%%%%%%%%%%%%%%%%%%%%% 
%%%%%%%%%%%%%%%%to search a region of the Pareto front%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function chromosome=nsga_IIDuv(fun,nvars,LB,UB,opts)

%% function nsga_2(pop,gen)
% is a multi-objective optimization function where the input arguments are 
% pop - Population size
% gen - Total number of generations
% 
% This functions is based on evolutionary algorithm for finding the optimal
% solution for multiple objective i.e. pareto front for the objectives. 
% Initially enter only the population size and the stoping criteria or
% the total number of generations after which the algorithm will
% automatically stopped. 
%
% You will be asked to enter the number of objective functions, the number
% of decision variables and the range space for the decision variables.
% Also you will have to define your own objective funciton by editing the
% evaluate_objective() function. A sample objective function is described
% in evaluate_objective.m. Kindly make sure that the objective function
% which you define match the number of objectives that you have entered as
% well as the number of decision variables that you have entered. The
% decision variable space is continuous for this function, but the
% objective space may or may not be continuous.
%
% Original algorithm NSGA-II was developed by researchers in Kanpur Genetic
% Algorithm Labarotary and kindly visit their website for more information
% http://www.iitk.ac.in/kangal/


%  Copyright (c) 2009, Aravind Seshadri
%  All rights reserved.
%
%  Redistribution and use in source and binary forms, with or without 
%  modification, are permitted provided that the following conditions are 
%  met:
%
%     * Redistributions of source code must retain the above copyright 
%       notice, this list of conditions and the following disclaimer.
%     * Redistributions in binary form must reproduce the above copyright 
%       notice, this list of conditions and the following disclaimer in 
%       the documentation and/or other materials provided with the distribution
%      
%  THIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS AND CONTRIBUTORS "AS IS" 
%  AND ANY EXPRESS OR IMPLIED WARRANTIES, INCLUDING, BUT NOT LIMITED TO, THE 
%  IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE 
%  ARE DISCLAIMED. IN NO EVENT SHALL THE COPYRIGHT OWNER OR CONTRIBUTORS BE 
%  LIABLE FOR ANY DIRECT, INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR 
%  CONSEQUENTIAL DAMAGES (INCLUDING, BUT NOT LIMITED TO, PROCUREMENT OF 
%  SUBSTITUTE GOODS OR SERVICES; LOSS OF USE, DATA, OR PROFITS; OR BUSINESS 
%  INTERRUPTION) HOWEVER CAUSED AND ON ANY THEORY OF LIABILITY, WHETHER IN 
%  CONTRACT, STRICT LIABILITY, OR TORT (INCLUDING NEGLIGENCE OR OTHERWISE) 
%  ARISING IN ANY WAY OUT OF THE USE OF THIS SOFTWARE, EVEN IF ADVISED OF THE 
%  POSSIBILITY OF SUCH DAMAGE.

%% Simple error checking
% Number of Arguments
% Check for the number of arguments. The two input arguments are necessary
% to run this function.
if nargin<5
    pop=50;gen=20;screenpareto=0;
else
    pop=opts.pop;gen=opts.gen;screenpareto=opts.screenpareto;
end
if screenpareto(1)~=0;screenpareto(1)=nvars(1)+screenpareto(1);end

% Both the input arguments need to of integer data type
if isnumeric(pop) == 0 || isnumeric(gen) == 0
    error('Both input arguments pop and gen should be integer datatype');
end

% Minimum population size has to be 20 individuals
if pop < 20
    error('Minimum population for running this function is 20');
end
if gen < 5
    error('Minimum number of generations is 5');
end
% Make sure pop and gen are integers
pop = round(pop);
gen = round(gen);
%number of decision variables
if size(nvars,2)==1;V=nvars;M=1;nvars(2)=M;else;V=nvars(1);M=nvars(2);end%first arg = # decision vars, second arg = # objectives;
%limits of decision variables
min_range=LB;
max_range=UB;


%% Objective Function
%fun = objective_description_function();

%% Initialize the population
% Population is initialized with random values which are within the
% specified range. Each chromosome consists of the decision variables. Also
% the value of the objective functions, rank and crowding distance
% information is also added to the chromosome vector but only the elements
% of the vector which has the decision variables are operated upon to
% perform the genetic operations like corssover and mutation.

if opts.InitChromosome==0;chromosome = initialize_variables(fun,M,V, min_range, max_range,pop);else; chromosome=opts.InitChromosome;end


%% Sort the initialized population
% Sort the population using non-domination-sort. This returns two columns
% for each individual which are the rank and the crowding distance
% corresponding to their position in the front they belong. At this stage
% the rank and the crowding distance for each chromosome is added to the
% chromosome vector for easy of computation.
chromosome = non_domination_sort_mod(chromosome, M,V);

%% Start the evolution process
% The following are performed in each generation
% * Select the parents which are fit for reproduction
% * Perfrom crossover and Mutation operator on the selected parents
% * Perform Selection from the parents and the offsprings
% * Replace the unfit individuals with the fit individuals to maintain a
%   constant population size.

for i = 1 : gen
    % Select the parents
    % Parents are selected for reproduction to generate offspring. The
    % original NSGA-II uses a binary tournament selection based on the
    % crowded-comparision operator. The arguments are 
    % pool - size of the mating pool. It is common to have this to be half the
    %        population size.
    % tour - Tournament size. Original NSGA-II uses a binary tournament
    %        selection, but to see the effect of tournament size this is kept
    %        arbitary, to be choosen by the user.
    pop=size(chromosome,1);
    pool = round(pop/2);
    tour = 2;
    % Selection process
    % A binary tournament selection is employed in NSGA-II. In a binary
    % tournament selection process two individuals are selected at random
    % and their fitness is compared. The individual with better fitness is
    % selcted as a parent. Tournament selection is carried out until the
    % pool size is filled. Basically a pool size is the number of parents
    % to be selected. The input arguments to the function
    % tournament_selection are chromosome, pool, tour. The function uses
    % only the information from last two elements in the chromosome vector.
    % The last element has the crowding distance information while the
    % penultimate element has the rank information. Selection is based on
    % rank and if individuals with same rank are encountered, crowding
    % distance is compared. A lower rank and higher crowding distance is
    % the selection criteria.
    
    parent_chromosome = tournament_selectionDuv(chromosome, pool, tour,screenpareto);

    % Perfrom crossover and Mutation operator
    % The original NSGA-II algorithm uses Simulated Binary Crossover (SBX) and
    % Polynomial  mutation. Crossover probability pc = 0.9 and mutation
    % probability is pm = 1/n, where n is the number of decision variables.
    % Both real-coded GA and binary-coded GA are implemented in the original
    % algorithm, while in this program only the real-coded GA is considered.
    % The distribution indeices for crossover and mutation operators as mu = 20
    % and mum = 20 respectively.
    mu = 20;
    mum = 20;
    offspring_chromosome = ...
        genetic_operator(fun,parent_chromosome, ...
        M, V, mu, mum, min_range, max_range);

    % Intermediate population
    % Intermediate population is the combined population of parents and
    % offsprings of the current generation. The population size is two
    % times the initial population.
    
    [main_pop,temp] = size(chromosome);
    [offspring_pop,temp] = size(offspring_chromosome);
    % temp is a dummy variable.
    clear temp
    % intermediate_chromosome is a concatenation of current population and
    % the offspring population.
    intermediate_chromosome(1:main_pop,:) = chromosome;
    intermediate_chromosome(main_pop + 1 : main_pop + offspring_pop,1 : M+V) = ...
        offspring_chromosome;

    % Non-domination-sort of intermediate population
    % The intermediate population is sorted again based on non-domination sort
    % before the replacement operator is performed on the intermediate
    % population.
    intermediate_chromosome = ...
        non_domination_sort_mod(intermediate_chromosome, M, V);
    % Perform Selection
    % Once the intermediate population is sorted only the best solution is
    % selected based on it rank and crowding distance. Each front is filled in
    % ascending order until the addition of population size is reached. The
    % last front is included in the population based on the individuals with
    % least crowding distance
    chromosome = replace_chromosomeDuv(intermediate_chromosome, M, V, pop,tour,screenpareto);
    if ~mod(i,round(gen/10))
        %clc
        fprintf('%d generations completed\n',i);
    end
        disp('plotting pareto')
        
        rr=floor(linspace(1,size(chromosome,1),100));

        if M==2;
            global x1data x2data
            x1data=-chromosome(rr,end-(M+1));
            x2data=-chromosome(rr,end-(M));
            x1data(isnan(x1data))=10000;
            x2data(isnan(x2data))=10000;
            figure(33);plot(x1data,x2data,'LineStyle','none','Marker','.','Color',[rand(1),rand(1),rand(1)]);hold on;xlabel(' objective 1');ylabel('objective 2');
            if ~isempty(x1data) & ~isempty(x2data);axis([median(x1data)-3*std(x1data), median(x1data)+3*std(x1data),median(x2data)-3*std(x2data), median(x2data)+3*std(x2data)]);end
        else
            if M==3;color=[rand(1),rand(1),rand(1)];
                x1data=-chromosome(rr,end-(M+1));
                x1data(isnan(x1data))=10000;
                x2data=-chromosome(rr,end-(M));
                x2data(isnan(x2data))=10000;
                x3data=-chromosome(rr,end-(M-1));
                x3data(isnan(x3data))=10000;
                figure(33);subplot(1,3,1);plot(x1data,x2data,'LineStyle','none','Marker','.','Color',color);hold on;xlabel(' objective 1');ylabel('objective 2');
                if ~isempty(x1data) & ~isempty(x2data);axis([median(x1data)-3*iqr(x1data), median(x1data)+3*iqr(x1data),median(x2data)-3*iqr(x2data), median(x2data)+3*iqr(x2data)]);end
                figure(33);subplot(1,3,2);plot(x1data,x3data,'LineStyle','none','Marker','.','Color',color);hold on;xlabel(' objective 1');ylabel('objective 3');
                if ~isempty(x1data) & ~isempty(x3data);axis([median(x1data)-3*iqr(x1data), median(x1data)+3*iqr(x1data),median(x3data)-3*iqr(x3data), median(x3data)+3*iqr(x3data)]);end
                figure(33);subplot(1,3,3);plot(x2data,x3data,'LineStyle','none','Marker','.','Color',color);hold on;xlabel(' objective 2');ylabel('objective 3');
                if ~isempty(x2data) & ~isempty(x3data);axis([median(x2data)-3*iqr(x2data), median(x2data)+3*iqr(x2data),median(x3data)-3*iqr(x3data), median(x3data)+3*iqr(x3data)]);end
            end
        end
end

if  screenpareto(1)~=0;
    no=screenpareto(1);Duvm=screenpareto(2);DuvM=screenpareto(3);
    chromosome=chromosome(chromosome(:,no)<=DuvM,:);
    chromosome=chromosome(chromosome(:,no)>=Duvm,:);
end



end
%__________________________________________________________________________
function f = evaluate_objective(fun, x, M, V)

%% function f = evaluate_objective(fun, x, M, V)
% Function to evaluate the objective functions for the given input vector
% x. x is an array of decision variables and f(1), f(2), etc are the
% objective functions. The algorithm always minimizes the objective
% function hence if you would like to maximize the function then multiply
% the function by negative one. M is the numebr of objective functions and
% V is the number of decision variables. 
%
% This functions is basically written by the user who defines his/her own
% objective function. Make sure that the M and V matches your initial user
% input. Make sure that the 
%
f=feval(fun,x);

%% Check for error
if length(f) ~= M
    error('The number of decision variables does not match you previous input. Kindly check your objective function');
end
end
%__________________________________________________________________________
function f = initialize_variables(fun, M,V, min_range, max_range, N)

%% function f = initialize_variables(N, M,V, min_tange, max_range) 
% This function initializes the chromosomes. Each chromosome has the
% following at this stage
%       * set of decision variables
%       * objective function values
% 
% where,
% N - Population size
% M - Number of objective functions
% V - Number of decision variables
% min_range - A vector of decimal values which indicate the minimum value
% for each decision variable.
% max_range - Vector of maximum possible values for decision variables.

%  Copyright (c) 2009, Aravind Seshadri
%  All rights reserved.
%
%  Redistribution and use in source and binary forms, with or without 
%  modification, are permitted provided that the following conditions are 
%  met:
%
%     * Redistributions of source code must retain the above copyright 
%       notice, this list of conditions and the following disclaimer.
%     * Redistributions in binary form must reproduce the above copyright 
%       notice, this list of conditions and the following disclaimer in 
%       the documentation and/or other materials provided with the distribution
%      
%  THIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS AND CONTRIBUTORS "AS IS" 
%  AND ANY EXPRESS OR IMPLIED WARRANTIES, INCLUDING, BUT NOT LIMITED TO, THE 
%  IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE 
%  ARE DISCLAIMED. IN NO EVENT SHALL THE COPYRIGHT OWNER OR CONTRIBUTORS BE 
%  LIABLE FOR ANY DIRECT, INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR 
%  CONSEQUENTIAL DAMAGES (INCLUDING, BUT NOT LIMITED TO, PROCUREMENT OF 
%  SUBSTITUTE GOODS OR SERVICES; LOSS OF USE, DATA, OR PROFITS; OR BUSINESS 
%  INTERRUPTION) HOWEVER CAUSED AND ON ANY THEORY OF LIABILITY, WHETHER IN 
%  CONTRACT, STRICT LIABILITY, OR TORT (INCLUDING NEGLIGENCE OR OTHERWISE) 
%  ARISING IN ANY WAY OUT OF THE USE OF THIS SOFTWARE, EVEN IF ADVISED OF THE 
%  POSSIBILITY OF SUCH DAMAGE.

min = min_range;
max = max_range;

% K is the total number of array elements. For ease of computation decision
% variables and objective functions are concatenated to form a single
% array. For crossover and mutation only the decision variables are used
% while for selection, only the objective variable are utilized.

K = M + V;

%% Initialize each chromosome
% For each chromosome perform the following (N is the population size)
for i = 1 : N
    % Initialize the decision variables based on the minimum and maximum
    % possible values. V is the number of decision variable. A random
    % number is picked between the minimum and maximum possible values for
    % the each decision variable.
    for j = 1 : V
        f(i,j) = min(j) + (max(j) - min(j))*rand(1);
    end
    % For ease of computation and handling data the chromosome also has the
    % vlaue of the objective function concatenated at the end. The elements
    % V + 1 to K has the objective function valued. 
    % The function evaluate_objective takes one chromosome at a time,
    % infact only the decision variables are passed to the function along
    % with information about the number of objective functions which are
    % processed and returns the value for the objective functions. These
    % values are now stored at the end of the chromosome itself.
    f(i,V + 1: K) = evaluate_objective(fun, f(i,:), M, V);
end
end
%__________________________________________________________________________
function f = tournament_selectionDuv(chromosome, pool_size, tour_size,screenpareto)

%% function tournament_selection(chromosome, pool_size, tour_size) 
% is the selection policy for selecting the individuals for the mating 
% pool. The selection is based on tournament selection. Argument 
% |chromosome| is the current generation population from which the 
% individuals are selected to form a mating pool of size |pool_size| after 
% performing tournament selection, with size of the tournament being 
% |tour_size|. By varying the tournament size the selection pressure can be
% adjusted. But for NSGA-II the tour_size is fixed to two, but the user may
% feel free to experiment with different tournament size. Also it has been
% observed that a tournament size of more than five has no significant
% meaning. 
%
%% Tournament selection process
% In a tournament selection process n individuals are selected at random,
% where n is equal to |tour_size|. From these individuals only one is selected
% and is added to the mating pool, where size of the mating pool is
% |pool_size|. Selection is performed based on two criteria. First and
% foremost is the rank or the front in which the solutions reside.
% Individuals with lower rank are selected. Secondly if the rank of two
% individuals are the same then, the crowding distance is compared.
% Individuals with greater crowding distance is selcted. 


%  Copyright (c) 2009, Aravind Seshadri
%  All rights reserved.
%
%  Redistribution and use in source and binary forms, with or without 
%  modification, are permitted provided that the following conditions are 
%  met:
%
%     * Redistributions of source code must retain the above copyright 
%       notice, this list of conditions and the following disclaimer.
%     * Redistributions in binary form must reproduce the above copyright 
%       notice, this list of conditions and the following disclaimer in 
%       the documentation and/or other materials provided with the distribution
%      
%  THIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS AND CONTRIBUTORS "AS IS" 
%  AND ANY EXPRESS OR IMPLIED WARRANTIES, INCLUDING, BUT NOT LIMITED TO, THE 
%  IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE 
%  ARE DISCLAIMED. IN NO EVENT SHALL THE COPYRIGHT OWNER OR CONTRIBUTORS BE 
%  LIABLE FOR ANY DIRECT, INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR 
%  CONSEQUENTIAL DAMAGES (INCLUDING, BUT NOT LIMITED TO, PROCUREMENT OF 
%  SUBSTITUTE GOODS OR SERVICES; LOSS OF USE, DATA, OR PROFITS; OR BUSINESS 
%  INTERRUPTION) HOWEVER CAUSED AND ON ANY THEORY OF LIABILITY, WHETHER IN 
%  CONTRACT, STRICT LIABILITY, OR TORT (INCLUDING NEGLIGENCE OR OTHERWISE) 
%  ARISING IN ANY WAY OUT OF THE USE OF THIS SOFTWARE, EVEN IF ADVISED OF THE 
%  POSSIBILITY OF SUCH DAMAGE.


%Duvm <= Duv <= DuvM ,where Duv is objective no;screen part of Pareto
%boundaryµ
if nargin > 3 & screenpareto(1)~=0;
    
    no=screenpareto(1);Duvm=screenpareto(2);DuvM=screenpareto(3);
    if sum(chromosome(:,no)<=DuvM)>=tour_size;chromosome=chromosome(chromosome(:,no)<=DuvM,:);end
    if sum(chromosome(:,no)>=Duvm)>=tour_size;chromosome=chromosome(chromosome(:,no)>=Duvm,:);;end

end


% Get the size of chromosome. The number of chromosome is not important
% while the number of elements in chromosome are important.
[pop, variables] = size(chromosome);
% The peunltimate element contains the information about rank.
rank = variables - 1;
% The last element contains information about crowding distance.
distance = variables;



% Until the mating pool is filled, perform tournament selection
for i = 1 : pool_size
    % Select n individuals at random, with where n = tour_size
    for j = 1 : tour_size
        % Select an individual at random
        
        candidate(j) = round(pop*rand(1));
        % Make sure that the array starts from one. 
        if candidate(j) == 0
            candidate(j) = 1;
        end
        if j > 1
            % Make sure that same candidate is not choosen.
            while ~isempty(find(candidate(1 : j - 1) == candidate(j)))
                candidate(j) = round(pop*rand(1));
                if candidate(j) == 0
                    candidate(j) = 1;
                end
            end
        end
    end
    % Collect information about the selected candidates.
    for j = 1 : tour_size
        c_obj_rank(j) = chromosome(candidate(j),rank);
        c_obj_distance(j) = chromosome(candidate(j),distance);
    end
    %c_obj_rank,c_obj_distance
    % Find the candidate with the least rank
    min_candidate = ...
        find(c_obj_rank == min(c_obj_rank));
    % If more than one candiate have the least rank then find the candidate
    % within that group having the maximum crowding distance.
    if length(min_candidate) ~= 1
        max_candidate = ...
        find(c_obj_distance(min_candidate) == max(c_obj_distance(min_candidate)));
        % If a few individuals have the least rank and have maximum crowding
        % distance, select only one individual (not at random). 
        if length(max_candidate) ~= 1
            max_candidate = max_candidate(1);
            
        end
        
        % Add the selected individual to the mating pool
        f(i,:) = chromosome(candidate(min_candidate(max_candidate)),:);
    else
        % Add the selected individual to the mating pool
         f(i,:) = chromosome(candidate(min_candidate(1)),:);

    end
end

end
