function xy=uv2xy(uvp)
xy(:,1)=9*uvp(:,1)./(12-16*uvp(:,2)+6*uvp(:,1));
xy(:,2)=4*uvp(:,2)./(12-16*uvp(:,2)+6*uvp(:,1));
end


function [x,x0,LB,UB]=setupX0_LB_UB__(SPDbuildertype,sources,nsources,minlambda,maxlambda,minwidth,maxwidth)
maxUB=10^10;minLB=10^(-10);

switch SPDbuildertype
    case 'mixer'
        maxrbas=10^3;
        minrbas=-1.*maxrbas;
        rbas_cor=3;
    otherwise
        maxrbas=1;%%rbas are actually fluxes 
        minrbas=0;
        rbas_cor=0;
end

if isempty(sources)
    UB=[maxlambda.*ones(1,nsources),maxwidth.*ones(1,nsources),maxrbas.*ones(1,nsources-rbas_cor)];   
    LB=[minlambda.*ones(1,nsources),minwidth.*ones(1,nsources),0.*ones(1,nsources-rbas_cor)]; 
    randleds=randperm(maxlambda);
    randleds=randleds((randleds>=minlambda)&(randleds<=maxlambda));
    randledsfwhm=rand(1,abs(nsources)).*maxwidth;
    x0=[randleds(1:nsources),randledsfwhm(1:nsources),maxrbas.*2.*(rand(1,nsources-rbas_cor)-0.5)];
    x=x0;
else %<0: fixed spds, rbas changes!!
    UB=[maxrbas.*ones(1,nsources-rbas_cor)];   
    LB=[minrbas.*ones(1,nsources-rbas_cor)]; 
    x0=[maxrbas.*2.*(rand(1,nsources-rbas_cor)-0.5)];
    x=x0;
    
    if strcmp(SPDbuildertype,'mixer');%incorporate source order into optimization
        UB=[UB,nsources.*ones(1,nsources)];
        LB=[LB,ones(1,nsources)];
        x0=[x0,randperm(nsources)];
        x=x0;
    end
    
end

%ensure starting value are consistent with UB and LB
x0(x0<LB)=LB(x0<LB);
x0(x0>UB)=UB(x0>UB);
x(x<LB)=LB(x<LB);
x(x>UB)=UB(x>UB);
end

function [x,x0,LB,UB]=setupX0_LB_UB(optim)
maxUB=10^10;minLB=10^(-10);

switch optim.type_
    case 'mixer'
        maxrbas=10^3;
        minrbas=-1.*maxrbas;
        rbas_cor=3;
    otherwise
        maxrbas=1;%%rbas are actually fluxes 
        minrbas=0;
        rbas_cor=0;
end

if isempty(optim.sp.sources)
    UB=[optim.maxlambda.*ones(1,optim.nsources),optim.maxwidth.*ones(1,optim.nsources),maxrbas.*ones(1,optim.nsources-rbas_cor)];   
    LB=[optim.minlambda.*ones(1,optim.nsources),optim.minwidth.*ones(1,optim.nsources),0.*ones(1,optim.nsources-rbas_cor)]; 
    randleds=randperm(optim.maxlambda);
    randleds=randleds((randleds>=optim.minlambda)&(randleds<=optim.maxlambda));
    randledsfwhm=rand(1,optim.nsources).*optim.maxwidth;
    x0=[randleds(1:optim.nsources),randledsfwhm(1:optim.nsources),maxrbas.*2.*(rand(1,optim.nsources-rbas_cor)-0.5)];
    x=x0;
else %<0: fixed spds, rbas changes!!
    UB=[maxrbas.*ones(1,optim.nsources-rbas_cor)];   
    LB=[minrbas.*ones(1,optim.nsources-rbas_cor)]; 
    x0=[maxrbas.*2.*(rand(1,optim.nsources-rbas_cor)-0.5)];
    x=x0;
end    
if strcmp(optim.type_,'mixer') & optim.usesourceorder==1;%incorporate source order into optimization
   UB=[UB,optim.nsources.*ones(1,optim.nsources)];
   LB=[LB,ones(1,optim.nsources)];
   x0=[x0,randperm(optim.nsources)];
   x=x0;
end


%ensure starting value are consistent with UB and LB
x0(x0<LB)=LB(x0<LB);
x0(x0>UB)=UB(x0>UB);
x(x<LB)=LB(x<LB);
x(x>UB)=UB(x>UB);
end
